package br.com.brindespro.quote;
import jakarta.persistence.*;import java.time.OffsetDateTime;
@Entity @Table(name="quote_files") public class QuoteFile { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id;@ManyToOne @JoinColumn(name="quote_id") public Quote quote;@Column(name="stored_name",nullable=false) public String storedName;@Column(name="original_name",nullable=false) public String originalName;@Column(name="mime_type",nullable=false) public String mimeType;@Column(name="size_bytes",nullable=false) public long sizeBytes;@Column(name="upload_token",unique=true) public String uploadToken;@Column(name="created_at",nullable=false) public OffsetDateTime createdAt=OffsetDateTime.now();protected QuoteFile(){} public QuoteFile(String storedName,String originalName,String mimeType,long sizeBytes){this.storedName=storedName;this.originalName=originalName;this.mimeType=mimeType;this.sizeBytes=sizeBytes;this.uploadToken=java.util.UUID.randomUUID().toString();} }
